    {
      "name": "find oak_wood",
      "description": "Player navigates to and finds the oak wood trees near spawn",
      "task_type": "find",
      "target_block": "minecraft:oak_wood",
      "rules": [
        {
          "rule_type": "position_inside_box",
          "description": "Player is within 5 blocks of the oak wood tree cluster (trees at ~3,0,3 and ~6,0,4)",
          "parameters": {
            "corner1": ["~-1", "~0", "~-1"],
            "corner2": ["~10", "~5", "~9"]
          }
